import json


def ch(s):
    return [[w, int(c)] for w, c in (t.rsplit('|', 1) for t in s.split())]


def F(frm, to, say, note):
    return {'from_': ch(frm), 'to': ch(to), 'say': say, 'note': note}


def H(e, x, y, en, pt, say, sayPt):
    return {'e': e, 'x': x, 'y': y, 'en': en, 'pt': pt, 'say': say, 'sayPt': sayPt}


def G(q, pt, opts, a, why):
    return {'q': q, 'pt': pt, 'opts': opts, 'a': a, 'why': why}


def TR(opts, a, why, q='Qual frase está certa?'):
    return {'q': q, 'opts': opts, 'a': a, 'why': why}


def EX(ic, en, tag, pt, use, ex, expt):
    return {'ic': ic, 'en': en, 'tag': tag, 'pt': pt, 'use': use, 'ex': [ex, expt]}


def RD(say, opts, a, why):
    return {'fig': '🎧', 'say': say, 'ask': 'Qual palavra você ouviu?', 'opts': opts, 'a': a, 'why': why}


def HU(say, opts, a, why, pic=False):
    d = {'fig': '🎧', 'say': say, 'ask': 'Ouça e toque na figura.' if pic else 'Ouça e toque na palavra.',
         'opts': [[o, ''] for o in opts] if pic else opts, 'a': a, 'why': why}
    if pic:
        d['pic'] = 1
    return d


def VBI(v, ic, pt, fi, fs, ex, expt, note):
    return {'v': v, 'ic': ic, 'pt': pt, 'f': [['eu', fi], ['ele/ela', fs]], 'ex': [ex, expt], 'note': note}


def CXI(text, pt, right, w1, w2):
    return {'text': text, 'pt': pt, 'opts': [right, w1, w2], 'a': 0}


def MOLD(label, slots, end=('.', '.')):
    return {'label': label, 'slots': [{'cat': c, 'opts': [list(o) for o in os_]} for c, os_ in slots], 'end': list(end)}


def MTR(ask, opts, a, why, say=None):
    d = {'ask': ask, 'opts': opts, 'a': a, 'why': why}
    if say:
        d['say'] = say
    return d


def MGAP(text, pt, opts, a, why, say):
    return {'text': text, 'pt': pt, 'opts': opts, 'a': a, 'why': why, 'say': say}


def MQ(ask, opts, a, why):
    return {'ask': ask, 'opts': opts, 'a': a, 'why': why}


def MS(ic, name, desc, prompt, chips, model, check, kw, tips, ok, reply, ph='Escreva a sua resposta aqui…'):
    return {'ic': ic, 'name': name, 'desc': desc, 'data': {'prompt': prompt, 'ph': ph, 'chips': chips, 'model': model,
            'check': check, 'kw': kw, 'tips': tips, 'ok': ok, 'reply': reply}}


RSORDER = ['rdg', 'pat', 'vplay', 'sbuild', 'build', 'order', 'balloons', 'dictate', 'soundlab', 'scene', 'dquiz',
           'scenebuild', 'produce', 'review', 'wrap']


def mk(n, title, sub, label, why, vocab, balloons, cover, cover_sub, cover_say, recap, teaser, cast, lines, quiz, rdg,
       dictate, produce, rs15, sc, names, stage, obra, gancho, hot, gap, trap, sticker, speakers, rule, mission_ic,
       exp, exp_scene, lab, hunt, vb, mr, cx):
    B = {
        'title': title, 'sub': sub, 'pattern_label': label, 'why': why,
        'vocab': [list(v) for v in vocab], 'balloons': [list(b) for b in balloons],
        'cover_art': {'s': cover[0], 'items': [[e, x, y, s, 'bob'] for e, x, y, s in cover[1]], 'seed': cover[2]},
        'cover_sub': cover_sub, 'cover_say': cover_say, 'wrap_recap': [list(r) for r in recap],
        'teaser': {'t': teaser[0], 'd': teaser[1]}, 'cast': {k: list(v) for k, v in cast.items()},
        'lines': [list(l) for l in lines],
        'quiz': [{'q': q, 'pt': pt, 'opts': [list(o) for o in op], 'a': a, 'line': li, 'why': w} for q, pt, op, a, li, w in quiz],
        'rdg_q': {'q': rdg[0], 'o': rdg[1], 'a': rdg[2], 'why': rdg[3]},
        'dictate': [list(d) for d in dictate], 'produce': produce, 'rs': dict(zip(RSORDER, rs15)), 'sc': sc,
    }
    X = {
        'n': n, 'review': True, 'names': list(names), 'stage': {'rs': stage[0], 'chars': [list(c) for c in stage[1]]},
        'obra': obra, 'gancho': list(gancho), 'hot': hot, 'gap': gap, 'trap': trap,
        'sticker': {'title': sticker[0], 'sub': sticker[1], 'rs': sticker[2], 'chars': [list(c) for c in sticker[3]]},
        'speakers': speakers, 'rule': rule, 'mission_ic': mission_ic,
    }
    XT = {'exp': exp, 'exp_scene': {'rs': exp_scene[0], 'lines': [list(l) for l in exp_scene[1]]}, 'lab': lab, 'hunt': hunt}
    return {'B': B, 'X': X, 'XT': XT, 'VB': vb, 'MR': mr, 'CX': cx}


def PA(t, e, p, v=0):
    return {'t': t, 'e': list(e), 'p': p, 'v': v}


def RULE(who, head, sub, say, uses, rules, tips, formula=None, pairs=None, pairsHead=None):
    r = {'who': who, 'head': head, 'sub': sub, 'say': list(say),
         'uses': [{'ico': a, 'tag': b, 'en': c, 'pt': d} for a, b, c, d in uses],
         'rules': [{'tag': a, 'c': b, 'text': c, 'ex': d} for a, b, c, d in rules], 'tips': tips}
    if formula:
        r['formula'] = formula
    if pairs:
        r['pairsHead'] = pairsHead
        r['pairs'] = [{'ico': a, 'a': b, 'b': c, 'pta': d, 'ptb': e, 'n': n_} for a, b, c, d, e, n_ in pairs]
    return r


def LAB(short, title, say, what, how, pt, ex, pairs, tip, phrase, rounds):
    return {'short': short, 'title': title, 'say': say, 'intro': {'what': what, 'how': how, 'pt': pt},
            'ex': [list(e) for e in ex], 'pairs': [list(p) for p in pairs], 'tip': tip, 'phrase': list(phrase), 'rounds': rounds}


def PR(prompt, ph, chips, model, check, kw, tips, ok, reply):
    return {'prompt': prompt, 'ph': ph, 'chips': chips, 'model': model, 'check': check, 'kw': kw, 'tips': tips,
            'ok': ok, 'reply': list(reply)}


